// 7. DESKS MAP (24 desks per class: 4 columns × 6 rows = 48 seats)
export function generateDesksForClass(classId: string, students: StudentRow[]): DeskWithSeats[] {
  return Array.from({ length: 20 }, (_, dIdx) => {
    const deskNum = dIdx + 1;
    const rowNum = Math.floor(dIdx / 4) + 1;
    const colNum = (dIdx % 4) + 1;
    const deskId = `desk-${classId}-${deskNum}`;

    const leftIdx = dIdx * 2;
    const rightIdx = dIdx * 2 + 1;

    const leftStudent = leftIdx < students.length ? students[leftIdx] : null;
    const rightStudent = rightIdx < students.length ? students[rightIdx] : null;

    return {
      id: deskId,
      class_id: classId,
      desk_number: deskNum,
      row_num: rowNum,
      col_num: colNum,
      created_at: '2026-08-15T00:00:00.000Z',
      seats: [
        {
          id: `seat-${classId}-${deskNum}-L`,
          desk_id: deskId,
          side: 'left',
          student_id: leftStudent ? leftStudent.id : null,
          student: leftStudent,
        },
        {
          id: `seat-${classId}-${deskNum}-R`,
          desk_id: deskId,
          side: 'right',
          student_id: rightStudent ? rightStudent.id : null,
          student: rightStudent,
        },
      ],
    };
  });
}

export const INITIAL_DESKS_MAP: Record<string, DeskWithSeats[]> = INITIAL_CLASSES.reduce((acc, cls) => {
  const classStudents = INITIAL_STUDENTS.filter((s) => s.class_id === cls.id);
  acc[cls.id] = generateDesksForClass(cls.id, classStudents);
  return acc;
}, {} as Record<string, DeskWithSeats[]>);

export const INITIAL_DESKS: DeskWithSeats[] = INITIAL_DESKS_MAP['c-6a1'];

